import type { BffNormalizedData } from 'services';

import type { PortfolioCardData, PortfolioPieChartData } from './types';

const PORTFOLIO_BIG_NUMBERS_COMPONENT_ID =
  'innovation-hub-overview-portfolio-big-numbers';

const PORTFOLIO_PIE_CHARTS_COMPONENT_ID =
  'innovation-hub-overview-portfolio-pie-charts';

export function getPortfolioBigNumbers(
  data: BffNormalizedData | null | undefined,
): PortfolioCardData[] {
  if (!data) return [];
  const flat = data['portfolio-big-numbers'];
  if (Array.isArray(flat)) return flat as PortfolioCardData[];
  const nested =
    data[PORTFOLIO_BIG_NUMBERS_COMPONENT_ID]?.['portfolio-big-numbers'];
  return Array.isArray(nested) ? (nested as PortfolioCardData[]) : [];
}

export function getPortfolioPieCharts(
  data: BffNormalizedData | null | undefined,
): PortfolioPieChartData[] {
  if (!data) return [];
  const flat = data['portfolio-pie-charts'];
  if (Array.isArray(flat)) return flat as PortfolioPieChartData[];
  const nested =
    data[PORTFOLIO_PIE_CHARTS_COMPONENT_ID]?.['portfolio-pie-charts'];
  return Array.isArray(nested) ? (nested as PortfolioPieChartData[]) : [];
}
